#include <vector>
#define main hecbench_original_main
#include "ecdh-cuda/main.cu"
#undef main
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"synchronized_kernel_loop_mean\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
struct Point{int x,y;bool infinity;};int mod(int x){return (x%17+17)%17;}int inverse(int a){for(int i=1;i<17;i++)if(mod(a*i)==1)return i;return 0;}Point plus(Point p,Point q){if(p.infinity)return q;if(q.infinity)return p;if(p.x==q.x&&mod(p.y+q.y)==0)return{0,0,true};int slope=mod((p.x==q.x&&p.y==q.y?3*p.x*p.x+2:q.y-p.y)*inverse(p.x==q.x&&p.y==q.y?2*p.y:q.x-p.x));int x=mod(slope*slope-p.x-q.x);return{x,mod(slope*(p.x-x)-p.y),false};}
int main(int argc,char**argv){int n=argc>1?atoi(argv[1]):4096,repeat=argc>2?atoi(argv[2]):10;Point point{0,0,true};for(int i=0;i<18;i++)point=plus(point,{5,1,false});std::vector<double>expected;for(int c=0;c<2;c++){expected.insert(expected.end(),n,point.x);expected.insert(expected.end(),n,point.y);}std::vector<int>x(n),y(n);int *dx,*dy;cudaMalloc(&dx,n*4);cudaMalloc(&dy,n*4);auto launch=[&](int c){if(c==1)k_slow<<<(n+255)/256,256>>>(18,5,1,dx,dy,17,2,n);else k_fast<<<(n+255)/256,256>>>(18,5,1,dx,dy,17,2,n);};launch(1);launch(2);cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){double total=0;std::vector<double>values;for(int c=1;c<=2;c++){auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)launch(c);cudaDeviceSynchronize();total+=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;cudaMemcpy(x.data(),dx,n*4,cudaMemcpyDeviceToHost);cudaMemcpy(y.data(),dy,n*4,cudaMemcpyDeviceToHost);for(int v:x)values.push_back(v);for(int v:y)values.push_back(v);}emit(trial,total,values,expected,repeat);}cudaFree(dx);cudaFree(dy);return 0;}
